const NODES = [{"id":0,"label":"rv","fullPath":"/home/runner/work/rv/rv","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":255.94,"y":336.26,"r":8.00},{"id":1,"label":"catalog-info.yaml","fullPath":"/home/runner/work/rv/rv/catalog-info.yaml","isDir":false,"size":334,"fileType":"Config","color":"#9C27B0","x":324.79,"y":345.86,"r":5.48},{"id":2,"label":"src","fullPath":"/home/runner/work/rv/rv/src","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":391.15,"y":446.08,"r":8.00},{"id":3,"label":"graph.rs","fullPath":"/home/runner/work/rv/rv/src/graph.rs","isDir":false,"size":2999,"fileType":"Rust","color":"#FF7043","x":459.14,"y":415.54,"r":8.43},{"id":4,"label":"svg.rs","fullPath":"/home/runner/work/rv/rv/src/svg.rs","isDir":false,"size":6313,"fileType":"Rust","color":"#FF7043","x":409.51,"y":399.60,"r":10.43},{"id":5,"label":"main.rs","fullPath":"/home/runner/work/rv/rv/src/main.rs","isDir":false,"size":3190,"fileType":"Rust","color":"#FF7043","x":457.60,"y":467.30,"r":8.57},{"id":6,"label":"interactive.rs","fullPath":"/home/runner/work/rv/rv/src/interactive.rs","isDir":false,"size":26077,"fileType":"Rust","color":"#FF7043","x":423.86,"y":503.16,"r":17.08},{"id":7,"label":"scanner.rs","fullPath":"/home/runner/work/rv/rv/src/scanner.rs","isDir":false,"size":3583,"fileType":"Rust","color":"#FF7043","x":349.54,"y":474.68,"r":8.85},{"id":8,"label":"layout.rs","fullPath":"/home/runner/work/rv/rv/src/layout.rs","isDir":false,"size":4391,"fileType":"Rust","color":"#FF7043","x":374.77,"y":520.00,"r":9.37},{"id":9,"label":"README.md","fullPath":"/home/runner/work/rv/rv/README.md","isDir":false,"size":3675,"fileType":"Markdown","color":"#9E9E9E","x":311.20,"y":393.04,"r":8.91},{"id":10,"label":"LICENSE","fullPath":"/home/runner/work/rv/rv/LICENSE","isDir":false,"size":1056,"fileType":"Other","color":"#BDBDBD","x":259.23,"y":427.54,"r":6.63},{"id":11,"label":"assets","fullPath":"/home/runner/work/rv/rv/assets","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":180.63,"y":445.28,"r":8.00},{"id":12,"label":"structure.png","fullPath":"/home/runner/work/rv/rv/assets/structure.png","isDir":false,"size":103086,"fileType":"Other","color":"#BDBDBD","x":179.85,"y":504.63,"r":30.00},{"id":13,"label":"structure.svg","fullPath":"/home/runner/work/rv/rv/assets/structure.svg","isDir":false,"size":35994,"fileType":"Other","color":"#BDBDBD","x":125.34,"y":466.25,"r":19.36},{"id":14,"label":"Cargo.toml","fullPath":"/home/runner/work/rv/rv/Cargo.toml","isDir":false,"size":248,"fileType":"Config","color":"#9C27B0","x":268.00,"y":376.48,"r":5.28},{"id":15,"label":"release.mk","fullPath":"/home/runner/work/rv/rv/release.mk","isDir":false,"size":2627,"fileType":"Other","color":"#BDBDBD","x":218.71,"y":390.31,"r":8.15},{"id":16,"label":"rust-toolchain.toml","fullPath":"/home/runner/work/rv/rv/rust-toolchain.toml","isDir":false,"size":150,"fileType":"Config","color":"#9C27B0","x":171.64,"y":368.14,"r":4.99},{"id":17,"label":"scripts","fullPath":"/home/runner/work/rv/rv/scripts","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":136.76,"y":315.65,"r":8.00},{"id":18,"label":"release.py","fullPath":"/home/runner/work/rv/rv/scripts/release.py","isDir":false,"size":14812,"fileType":"Python","color":"#3F51B5","x":80.00,"y":304.75,"r":13.86},{"id":19,"label":".release.env","fullPath":"/home/runner/work/rv/rv/.release.env","isDir":false,"size":307,"fileType":"Other","color":"#BDBDBD","x":238.28,"y":283.92,"r":5.42},{"id":20,"label":".gitignore","fullPath":"/home/runner/work/rv/rv/.gitignore","isDir":false,"size":63,"fileType":"Other","color":"#BDBDBD","x":209.48,"y":335.50,"r":4.64},{"id":21,"label":"Makefile","fullPath":"/home/runner/work/rv/rv/Makefile","isDir":false,"size":879,"fileType":"Other","color":"#BDBDBD","x":189.23,"y":290.29,"r":6.40},{"id":22,"label":"Formula","fullPath":"/home/runner/work/rv/rv/Formula","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":199.64,"y":231.42,"r":8.00},{"id":23,"label":"rv.rb","fullPath":"/home/runner/work/rv/rv/Formula/rv.rb","isDir":false,"size":1288,"fileType":"Other","color":"#BDBDBD","x":167.31,"y":183.01,"r":6.91},{"id":24,"label":"CONTRIBUTING.md","fullPath":"/home/runner/work/rv/rv/CONTRIBUTING.md","isDir":false,"size":1391,"fileType":"Markdown","color":"#9E9E9E","x":274.73,"y":250.69,"r":7.02},{"id":25,"label":".github","fullPath":"/home/runner/work/rv/rv/.github","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":351.13,"y":224.53,"r":8.00},{"id":26,"label":"workflows","fullPath":"/home/runner/work/rv/rv/.github/workflows","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":348.17,"y":138.53,"r":8.00},{"id":27,"label":"release.yml","fullPath":"/home/runner/work/rv/rv/.github/workflows/release.yml","isDir":false,"size":8645,"fileType":"Config","color":"#9C27B0","x":298.31,"y":118.00,"r":11.53},{"id":28,"label":"ci.yml","fullPath":"/home/runner/work/rv/rv/.github/workflows/ci.yml","isDir":false,"size":2309,"fileType":"Config","color":"#9C27B0","x":346.72,"y":80.00,"r":7.89},{"id":29,"label":"generate-viz.yml","fullPath":"/home/runner/work/rv/rv/.github/workflows/generate-viz.yml","isDir":false,"size":4020,"fileType":"Config","color":"#9C27B0","x":396.81,"y":117.55,"r":9.13},{"id":30,"label":"ISSUE_TEMPLATE","fullPath":"/home/runner/work/rv/rv/.github/ISSUE_TEMPLATE","isDir":true,"size":0,"fileType":"Directory","color":"#4CAF50","x":431.55,"y":220.87,"r":8.00},{"id":31,"label":"feature_request.md","fullPath":"/home/runner/work/rv/rv/.github/ISSUE_TEMPLATE/feature_request.md","isDir":false,"size":344,"fileType":"Markdown","color":"#9E9E9E","x":473.44,"y":186.75,"r":5.50},{"id":32,"label":"bug_report.md","fullPath":"/home/runner/work/rv/rv/.github/ISSUE_TEMPLATE/bug_report.md","isDir":false,"size":500,"fileType":"Markdown","color":"#9E9E9E","x":476.78,"y":251.10,"r":5.81},{"id":33,"label":"prek.toml","fullPath":"/home/runner/work/rv/rv/prek.toml","isDir":false,"size":1223,"fileType":"Config","color":"#9C27B0","x":288.09,"y":302.13,"r":6.83},{"id":34,"label":"Cargo.lock","fullPath":"/home/runner/work/rv/rv/Cargo.lock","isDir":false,"size":8689,"fileType":"Other","color":"#BDBDBD","x":336.19,"y":298.51,"r":11.55}];
const EDGES = [{"from":0,"to":1},{"from":0,"to":2},{"from":2,"to":3},{"from":2,"to":4},{"from":2,"to":5},{"from":2,"to":6},{"from":2,"to":7},{"from":2,"to":8},{"from":0,"to":9},{"from":0,"to":10},{"from":0,"to":11},{"from":11,"to":12},{"from":11,"to":13},{"from":0,"to":14},{"from":0,"to":15},{"from":0,"to":16},{"from":0,"to":17},{"from":17,"to":18},{"from":0,"to":19},{"from":0,"to":20},{"from":0,"to":21},{"from":0,"to":22},{"from":22,"to":23},{"from":0,"to":24},{"from":0,"to":25},{"from":25,"to":26},{"from":26,"to":27},{"from":26,"to":28},{"from":26,"to":29},{"from":25,"to":30},{"from":30,"to":31},{"from":30,"to":32},{"from":0,"to":33},{"from":0,"to":34}];
const CHILDREN_MAP = {"2":[3,4,5,6,7,8],"22":[23],"30":[31,32],"17":[18],"0":[1,2,9,10,11,14,15,16,17,19,20,21,22,24,25,33,34],"11":[12,13],"26":[27,28,29],"25":[26,30]};

// === State ===
let scale = 1;
let panX = 0, panY = 0;
let isPanning = false;
let panStartX = 0, panStartY = 0;
let panStartPanX = 0, panStartPanY = 0;
let isDraggingNode = false;
let dragNodeId = null;
let dragOffsetX = 0, dragOffsetY = 0;
let hoveredNodeId = null;
let collapsedDirs = new Set();
let hiddenNodes = new Set();
let searchMatches = new Set();

const svg = document.getElementById('graph-svg');
const panZoomGroup = document.getElementById('pan-zoom-group');
const edgesGroup = document.getElementById('edges-group');
const nodesGroup = document.getElementById('nodes-group');
const labelsGroup = document.getElementById('labels-group');
const tooltip = document.getElementById('tooltip');
const searchInput = document.getElementById('search-input');
const searchCount = document.getElementById('search-count');

const nodeEls = nodesGroup.querySelectorAll('.node');
const edgeEls = edgesGroup.querySelectorAll('.edge');
const labelEls = labelsGroup.querySelectorAll('text');

// Index elements by data-id
const nodeElById = {};
nodeEls.forEach(el => { nodeElById[el.getAttribute('data-id')] = el; });
const labelElById = {};
labelEls.forEach(el => { labelElById[el.getAttribute('data-label-for')] = el; });

// Build edge index: nodeId -> [edge indices]
const edgesByNode = {};
edgeEls.forEach((el, idx) => {
  const from = el.getAttribute('data-from');
  const to = el.getAttribute('data-to');
  if (!edgesByNode[from]) edgesByNode[from] = [];
  if (!edgesByNode[to]) edgesByNode[to] = [];
  edgesByNode[from].push(idx);
  edgesByNode[to].push(idx);
});

// Build neighbor index
const neighborsByNode = {};
EDGES.forEach(e => {
  if (!neighborsByNode[e.from]) neighborsByNode[e.from] = [];
  if (!neighborsByNode[e.to]) neighborsByNode[e.to] = [];
  neighborsByNode[e.from].push(e.to);
  neighborsByNode[e.to].push(e.from);
});

// === Transform ===
function applyTransform() {
  panZoomGroup.setAttribute('transform', `translate(${panX},${panY}) scale(${scale})`);
}

// === Zoom ===
svg.addEventListener('wheel', (e) => {
  e.preventDefault();
  const rect = svg.getBoundingClientRect();
  const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
  const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
  // Mouse position in SVG coordinate space
  const mx = (e.clientX - rect.left) / rect.width * svgW;
  const my = (e.clientY - rect.top) / rect.height * svgH;

  const oldScale = scale;
  const zoomFactor = e.deltaY < 0 ? 1.12 : 1 / 1.12;
  scale = Math.min(Math.max(scale * zoomFactor, 0.1), 30);

  // Adjust pan so zoom is centered on mouse
  panX = mx - (mx - panX) * (scale / oldScale);
  panY = my - (my - panY) * (scale / oldScale);

  applyTransform();
}, { passive: false });

// === Pan ===
svg.addEventListener('mousedown', (e) => {
  // Check if we hit a node
  const target = e.target;
  if (target.classList.contains('node')) {
    const nodeId = parseInt(target.getAttribute('data-id'));
    const nodeData = NODES[nodeId];

    // If it's a directory and not shift-held, toggle collapse
    if (nodeData && nodeData.isDir && !e.shiftKey) {
      toggleCollapse(nodeId);
      return;
    }

    // Start dragging
    isDraggingNode = true;
    dragNodeId = nodeId;
    const rect = svg.getBoundingClientRect();
    const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
    const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
    const mx = (e.clientX - rect.left) / rect.width * svgW;
    const my = (e.clientY - rect.top) / rect.height * svgH;
    const worldX = (mx - panX) / scale;
    const worldY = (my - panY) / scale;
    dragOffsetX = worldX - nodeData.x;
    dragOffsetY = worldY - nodeData.y;
    e.preventDefault();
    return;
  }

  isPanning = true;
  panStartX = e.clientX;
  panStartY = e.clientY;
  panStartPanX = panX;
  panStartPanY = panY;
  svg.style.cursor = 'grabbing';
});

window.addEventListener('mousemove', (e) => {
  if (isPanning) {
    const rect = svg.getBoundingClientRect();
    const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
    const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
    const dx = (e.clientX - panStartX) / rect.width * svgW;
    const dy = (e.clientY - panStartY) / rect.height * svgH;
    panX = panStartPanX + dx;
    panY = panStartPanY + dy;
    applyTransform();
    return;
  }
  if (isDraggingNode && dragNodeId !== null) {
    const rect = svg.getBoundingClientRect();
    const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
    const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
    const mx = (e.clientX - rect.left) / rect.width * svgW;
    const my = (e.clientY - rect.top) / rect.height * svgH;
    const worldX = (mx - panX) / scale;
    const worldY = (my - panY) / scale;
    const newX = worldX - dragOffsetX;
    const newY = worldY - dragOffsetY;

    // Update data
    NODES[dragNodeId].x = newX;
    NODES[dragNodeId].y = newY;

    // Update node circle
    const el = nodeElById[dragNodeId];
    if (el) {
      el.setAttribute('cx', newX.toFixed(1));
      el.setAttribute('cy', newY.toFixed(1));
    }

    // Update label
    const lbl = labelElById[dragNodeId];
    if (lbl) {
      lbl.setAttribute('x', newX.toFixed(1));
      lbl.setAttribute('y', (newY + NODES[dragNodeId].r + 12).toFixed(1));
    }

    // Update connected edges
    (edgesByNode[dragNodeId] || []).forEach(idx => {
      const edgeEl = edgeEls[idx];
      const fromId = edgeEl.getAttribute('data-from');
      const toId = edgeEl.getAttribute('data-to');
      const fromNode = NODES[fromId];
      const toNode = NODES[toId];
      edgeEl.setAttribute('x1', fromNode.x.toFixed(1));
      edgeEl.setAttribute('y1', fromNode.y.toFixed(1));
      edgeEl.setAttribute('x2', toNode.x.toFixed(1));
      edgeEl.setAttribute('y2', toNode.y.toFixed(1));
    });

    e.preventDefault();
    return;
  }

  // Hover detection
  handleHover(e);
});

window.addEventListener('mouseup', () => {
  isPanning = false;
  isDraggingNode = false;
  dragNodeId = null;
  svg.style.cursor = '';
});

// === Hover / Tooltip ===
function handleHover(e) {
  const target = document.elementFromPoint(e.clientX, e.clientY);
  if (target && target.classList.contains('node')) {
    const nodeId = parseInt(target.getAttribute('data-id'));
    if (nodeId !== hoveredNodeId) {
      hoveredNodeId = nodeId;
      highlightNode(nodeId);
      showTooltip(e, nodeId);
    } else {
      moveTooltip(e);
    }
  } else {
    if (hoveredNodeId !== null) {
      hoveredNodeId = null;
      clearHighlight();
      hideTooltip();
    }
  }
}

function highlightNode(nodeId) {
  const connectedNodes = new Set([nodeId]);
  const connectedEdges = new Set();

  (edgesByNode[nodeId] || []).forEach(idx => {
    connectedEdges.add(idx);
    const el = edgeEls[idx];
    connectedNodes.add(parseInt(el.getAttribute('data-from')));
    connectedNodes.add(parseInt(el.getAttribute('data-to')));
  });

  // Dim everything, then highlight connected
  nodeEls.forEach(el => {
    const id = parseInt(el.getAttribute('data-id'));
    if (connectedNodes.has(id)) {
      el.classList.add('highlighted');
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
      el.classList.remove('highlighted');
    }
  });

  edgeEls.forEach((el, idx) => {
    if (connectedEdges.has(idx)) {
      el.classList.add('highlighted');
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
      el.classList.remove('highlighted');
    }
  });

  labelEls.forEach(el => {
    const forId = parseInt(el.getAttribute('data-label-for'));
    if (connectedNodes.has(forId)) {
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
    }
  });
}

function clearHighlight() {
  nodeEls.forEach(el => {
    el.classList.remove('highlighted', 'dimmed');
    // Restore search match state
    const id = parseInt(el.getAttribute('data-id'));
    if (searchMatches.size > 0 && searchMatches.has(id)) {
      el.classList.add('search-match');
    }
  });
  edgeEls.forEach(el => el.classList.remove('highlighted', 'dimmed'));
  labelEls.forEach(el => el.classList.remove('dimmed'));
  // Reapply collapse hiding
  applyVisibility();
}

function formatSize(bytes) {
  if (bytes === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let s = bytes;
  let i = 0;
  while (s >= 1024 && i < units.length - 1) { s /= 1024; i++; }
  return i === 0 ? `${bytes} B` : `${s.toFixed(1)} ${units[i]}`;
}

function showTooltip(e, nodeId) {
  const node = NODES[nodeId];
  if (!node) return;
  let html = `
${node.label}`;
  html += `
${node.fullPath}`;
  html += `
Type: ${node.fileType}`;
  if (!node.isDir) {
    html += `
Size: ${formatSize(node.size)}`;
  }
  if (node.isDir) {
    const childCount = (CHILDREN_MAP[nodeId] || []).length;
    const isCollapsed = collapsedDirs.has(nodeId);
    html += `
Children: ${childCount}`;
    html += `
Click to ${isCollapsed ? 'expand' : 'collapse'}`;
  } else {
    html += `
Shift+drag to move`;
  }
  tooltip.innerHTML = html;
  tooltip.style.display = 'block';
  moveTooltip(e);
}

function moveTooltip(e) {
  const pad = 16;
  let x = e.clientX + pad;
  let y = e.clientY + pad;
  // Keep tooltip in viewport
  const rect = tooltip.getBoundingClientRect();
  if (x + rect.width > window.innerWidth) x = e.clientX - rect.width - pad;
  if (y + rect.height > window.innerHeight) y = e.clientY - rect.height - pad;
  tooltip.style.left = x + 'px';
  tooltip.style.top = y + 'px';
}

function hideTooltip() {
  tooltip.style.display = 'none';
}

// === Collapse / Expand Directories ===
function getAllDescendants(nodeId) {
  const descendants = new Set();
  const queue = [...(CHILDREN_MAP[nodeId] || [])];
  while (queue.length > 0) {
    const id = queue.pop();
    if (descendants.has(id)) continue;
    descendants.add(id);
    (CHILDREN_MAP[id] || []).forEach(child => queue.push(child));
  }
  return descendants;
}

function toggleCollapse(nodeId) {
  if (collapsedDirs.has(nodeId)) {
    collapsedDirs.delete(nodeId);
  } else {
    collapsedDirs.add(nodeId);
  }
  recomputeHidden();
  applyVisibility();

  // Update directory visual indicator
  const el = nodeElById[nodeId];
  if (el) {
    if (collapsedDirs.has(nodeId)) {
      el.classList.add('collapsed-dir');
    } else {
      el.classList.remove('collapsed-dir');
    }
  }
}

function recomputeHidden() {
  hiddenNodes.clear();
  collapsedDirs.forEach(dirId => {
    getAllDescendants(dirId).forEach(id => hiddenNodes.add(id));
  });
}

function applyVisibility() {
  nodeEls.forEach(el => {
    const id = parseInt(el.getAttribute('data-id'));
    el.style.display = hiddenNodes.has(id) ? 'none' : '';
  });
  edgeEls.forEach(el => {
    const from = parseInt(el.getAttribute('data-from'));
    const to = parseInt(el.getAttribute('data-to'));
    el.style.display = (hiddenNodes.has(from) || hiddenNodes.has(to)) ? 'none' : '';
  });
  labelEls.forEach(el => {
    const forId = parseInt(el.getAttribute('data-label-for'));
    el.style.display = hiddenNodes.has(forId) ? 'none' : '';
  });
}

// === Search ===
function handleSearch() {
  const query = searchInput.value.trim().toLowerCase();
  searchMatches.clear();

  if (query === '') {
    searchCount.textContent = '';
    nodeEls.forEach(el => {
      el.classList.remove('search-match', 'dimmed');
    });
    edgeEls.forEach(el => el.classList.remove('dimmed'));
    labelEls.forEach(el => el.classList.remove('dimmed'));
    return;
  }

  NODES.forEach(node => {
    if (node.label.toLowerCase().includes(query) || node.fullPath.toLowerCase().includes(query)) {
      searchMatches.add(node.id);
    }
  });

  searchCount.textContent = `${searchMatches.size} match${searchMatches.size !== 1 ? 'es' : ''}`;

  // Highlight matches, dim others
  nodeEls.forEach(el => {
    const id = parseInt(el.getAttribute('data-id'));
    if (searchMatches.has(id)) {
      el.classList.add('search-match');
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
      el.classList.remove('search-match');
    }
  });

  edgeEls.forEach(el => {
    const from = parseInt(el.getAttribute('data-from'));
    const to = parseInt(el.getAttribute('data-to'));
    if (searchMatches.has(from) && searchMatches.has(to)) {
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
    }
  });

  labelEls.forEach(el => {
    const forId = parseInt(el.getAttribute('data-label-for'));
    if (searchMatches.has(forId)) {
      el.classList.remove('dimmed');
    } else {
      el.classList.add('dimmed');
    }
  });

  // Auto-pan to first match
  if (searchMatches.size > 0) {
    const firstId = searchMatches.values().next().value;
    panToNode(firstId);
  }
}

function panToNode(nodeId) {
  const node = NODES[nodeId];
  if (!node) return;
  const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
  const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
  // Center the node in the viewport
  const targetScale = Math.max(scale, 1.5);
  panX = svgW / 2 - node.x * targetScale;
  panY = svgH / 2 - node.y * targetScale;
  scale = targetScale;
  applyTransform();
}

searchInput.addEventListener('input', handleSearch);

// === Keyboard shortcuts ===
document.addEventListener('keydown', (e) => {
  // Ctrl+F or Cmd+F => focus search
  if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
    e.preventDefault();
    searchInput.focus();
    searchInput.select();
  }
  // Escape => clear search, reset view
  if (e.key === 'Escape') {
    searchInput.value = '';
    searchInput.blur();
    handleSearch();
    // Reset pan/zoom
    scale = 1;
    panX = 0;
    panY = 0;
    applyTransform();
    // Clear collapsed
    collapsedDirs.clear();
    recomputeHidden();
    applyVisibility();
    nodeEls.forEach(el => el.classList.remove('collapsed-dir'));
  }
});

// === Fit to view on load ===
(function() {
  if (NODES.length === 0) return;
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  NODES.forEach(n => {
    if (n.x - n.r < minX) minX = n.x - n.r;
    if (n.x + n.r > maxX) maxX = n.x + n.r;
    if (n.y - n.r < minY) minY = n.y - n.r;
    if (n.y + n.r > maxY) maxY = n.y + n.r;
  });
  const svgW = parseFloat(svg.getAttribute('viewBox').split(' ')[2]);
  const svgH = parseFloat(svg.getAttribute('viewBox').split(' ')[3]);
  const graphW = maxX - minX || 1;
  const graphH = maxY - minY || 1;
  const padding = 60;
  const sx = (svgW - padding * 2) / graphW;
  const sy = (svgH - padding * 2) / graphH;
  scale = Math.min(sx, sy, 3);
  panX = (svgW - graphW * scale) / 2 - minX * scale;
  panY = (svgH - graphH * scale) / 2 - minY * scale;
  applyTransform();
})();
